import net.minecraft.client.gui.GuiGraphics
import net.minecraft.client.gui.components.Button
import net.minecraft.client.gui.components.EditBox
import net.minecraft.client.gui.screens.Screen
import net.minecraft.network.chat.Component

class InventoryButtonsGui : Screen(Component.literal("Настройка кнопок инвентаря")) {
    private lateinit var iconField: EditBox
    private lateinit var commandField: EditBox
    private lateinit var tooltipField: EditBox
    private var editingIndex: Int = -1

    override fun init() {
        val centerX = width / 2
        val startY = 60
        iconField = TransparentEditBox(font, centerX - 170, startY, 110, 18, Component.literal("Иконка"), "minecraft:ender_chest")
        addRenderableWidget(iconField)

        commandField = TransparentEditBox(font, centerX - 55, startY, 110, 18, Component.literal("Команда"), "/storage или текст")
        addRenderableWidget(commandField)

        tooltipField = TransparentEditBox(font, centerX + 60, startY, 110, 18, Component.literal("Подсказка"), "Текст при наведении")
        addRenderableWidget(tooltipField)
        val btnText = if (editingIndex >= 0) "§a✔ Сохранить" else "§a+ Добавить"
        addRenderableWidget(
            Button.builder(Component.literal(btnText)) { _ ->
                saveCurrentButton()
            }.bounds(centerX - 120, startY + 24, 115, 20).build()
        )

        val cancelText = if (editingIndex >= 0) "§c✖ Отмена" else "§c✖ Отмена"
        addRenderableWidget(
            Button.builder(Component.literal(cancelText)) { _ ->
                cancelEditing()
            }.bounds(centerX, startY + 24, 60, 20).build()
        )

        addRenderableWidget(
            Button.builder(Component.literal("§e↺ Очистить")) { _ ->
                iconField.value = ""
                commandField.value = ""
                tooltipField.value = ""
            }.bounds(centerX + 60, startY + 24, 60, 20).build()
        )

        rebuildList()
    }

    private fun saveCurrentButton() {
        val icon = iconField.value?.trim() ?: ""
        val command = commandField.value?.trim() ?: ""
        val tooltip = tooltipField.value?.trim() ?: ""
        if (icon.isBlank() || command.isBlank()) return

        val buttons = InventoryButtonsManager.getButtons().toMutableList()
        if (editingIndex >= 0 && editingIndex < buttons.size) {
            buttons[editingIndex] = InventoryButton(
                buttons[editingIndex].index, icon, command, tooltip
            )
            editingIndex = -1
        } else {
            val nextIndex = (buttons.maxOfOrNull { it.index } ?: -1) + 1
            if (nextIndex < InventoryButton.MAX_TABS) {
                buttons.add(InventoryButton(nextIndex, icon, command, tooltip))
            }
        }
        InventoryButtonsManager.setButtons(buttons)
        iconField.value = ""
        commandField.value = ""
        tooltipField.value = ""
        rebuildList()
    }

    private fun cancelEditing() {
        editingIndex = -1
        iconField.value = ""
        commandField.value = ""
        tooltipField.value = ""
        rebuildList()
    }

    private fun rebuildList() {
        children().filterIsInstance<Button>().filter {
            val s = it.message.string
            s.startsWith("✕") || s.startsWith("✎") || s.startsWith("▲") || s.startsWith("▼")
        }.forEach { removeWidget(it) }

        val buttons = InventoryButtonsManager.getButtons()
        val centerX = width / 2
        val startY = 110

        for ((listIndex, btn) in buttons.withIndex()) {
            val y = startY + listIndex * 30

            if (listIndex > 0) {
                addRenderableWidget(
                    Button.builder(Component.literal("▲")) { _ ->
                        moveButton(listIndex, -1)
                    }.bounds(centerX - 190, y + 2, 18, 18).build()
                )
            }

            if (listIndex < buttons.size - 1) {
                addRenderableWidget(
                    Button.builder(Component.literal("▼")) { _ ->
                        moveButton(listIndex, 1)
                    }.bounds(centerX - 190, y + 2, 18, 18).build()
                )
            }

            addRenderableWidget(
                Button.builder(Component.literal("✎")) { _ ->
                    editingIndex = listIndex
                    iconField.value = btn.icon ?: ""
                    commandField.value = btn.command ?: ""
                    tooltipField.value = btn.tooltip ?: ""
                    rebuildList()
                }.bounds(centerX + 155, y + 2, 18, 18).build()
            )

            addRenderableWidget(
                Button.builder(Component.literal("✕")) { _ ->
                    val list = InventoryButtonsManager.getButtons().toMutableList()
                    if (listIndex < list.size) {
                        list.removeAt(listIndex)
                        list.forEachIndexed { i, b -> b.index = i }
                        InventoryButtonsManager.setButtons(list)
                        if (editingIndex == listIndex) editingIndex = -1
                        rebuildList()
                    }
                }.bounds(centerX + 176, y + 2, 18, 18).build()
            )
        }
    }

    private fun moveButton(index: Int, direction: Int) {
        val buttons = InventoryButtonsManager.getButtons().toMutableList()
        val targetIndex = index + direction
        if (targetIndex < 0 || targetIndex >= buttons.size) return

        val temp = buttons[index]
        buttons[index] = buttons[targetIndex]
        buttons[targetIndex] = temp

        buttons.forEachIndexed { i, b -> b.index = i }
        InventoryButtonsManager.setButtons(buttons)

        if (editingIndex == index) editingIndex = targetIndex
        else if (editingIndex == targetIndex) editingIndex = index

        rebuildList()
    }

    override fun renderBackground(graphics: GuiGraphics, mouseX: Int, mouseY: Int, delta: Float) {
        graphics.fill(0, 0, width, height, 0xD0101010.toInt())
    }

    override fun render(graphics: GuiGraphics, mouseX: Int, mouseY: Int, delta: Float) {
        renderBackground(graphics, mouseX, mouseY, delta)

        val centerX = width / 2
        val startY = 60

        graphics.drawCenteredString(font, "§6§l⚙ Кнопки инвентаря", centerX, 10, 0xFFFFFF)
